<?php
/**
 * Offline, blocked-by-default contract for the one owner-approved fishing-stay cohort.
 * Input must be generated by the read-only builder; no WordPress credentials or writes.
 */
define('ABSPATH', __DIR__);
class WP_Error { public $code; public function __construct($code, $message = '') { $this->code=$code; } }
function is_wp_error($v) { return $v instanceof WP_Error; }
function add_action($name, $fn) { return true; }
function wp_kses($html, $allowed, $protocols) { return $html; }
$posts=array(); $writes=0; $options=array();
function get_post($id) { global $posts; return $posts[$id]??null; }
function wp_update_post($data,$returnError=false) { global $writes; $writes++; return $data['ID']; }
function add_option($key,$value,$deprecated='',$autoload='yes') { global $options; $options[$key]=$value; return true; }
function get_option($key,$default=false) { global $options; return $options[$key]??$default; }
function must($value,$reason) { if (!$value) throw new RuntimeException($reason); }
require dirname(__DIR__) . '/na-ryby-git-publisher.php';

$manifest=json_decode(stream_get_contents(STDIN),true);
must(is_array($manifest) && $manifest['schema_version']===9,'bad input candidate');
$valid=NRY_Git_Publisher::validate_manifest($manifest);
must(!is_wp_error($valid),'exact v9 candidate must validate');
must($valid['edits'][0]['post_id']===59891,'wrong post');

$bad=$manifest;
$bad['edits'][0]['insert_html'].='<script>bad()</script>';
must(is_wp_error(NRY_Git_Publisher::validate_manifest($bad)),'unapproved HTML accepted');
$bad=$manifest;
$bad['edits'][0]['insert_html']=str_replace('5QoXiSqx','other',$bad['edits'][0]['insert_html']);
must(is_wp_error(NRY_Git_Publisher::validate_manifest($bad)),'wrong Dognet attribution accepted');
$bad=$manifest;
$bad['edits'][0]['insert_html']=str_replace('j3d7tsgc','wrong-id',$bad['edits'][0]['insert_html']);
must(is_wp_error(NRY_Git_Publisher::validate_manifest($bad)),'wrong Slevomat attribution accepted');
$bad=$manifest;
$bad['edits'][0]['source_sha256']=str_repeat('0',64);
must(is_wp_error(NRY_Git_Publisher::validate_manifest($bad)),'unbound source hash accepted');
$bad=$manifest;
$bad['edits'][0]['post_id']=59271;
must(is_wp_error(NRY_Git_Publisher::validate_manifest($bad)),'different post accepted');
$bad=$manifest;
$bad['edits'][]=$manifest['edits'][0];
must(is_wp_error(NRY_Git_Publisher::validate_manifest($bad)),'multiple post scope accepted');
$bad=$manifest;
$bad['schema_version']=8;
must(is_wp_error(NRY_Git_Publisher::validate_manifest($bad)),'v8 internal-only restriction was weakened');

// A matching slug, bytes and modified date are insufficient: server-side raw SHA still wins.
$edit=$manifest['edits'][0];
$posts[59891]=(object)array('ID'=>59891,'post_type'=>'post','post_status'=>'publish',
    'post_name'=>$edit['slug'],'post_modified_gmt'=>$edit['source_modified_gmt'],
    'post_content'=>str_repeat('x',$edit['source_min_bytes']));
$rows=NRY_Git_Publisher::plan($valid);
must($rows[0]['status']==='blocked'
    && $rows[0]['reason']==='source_modified_or_bytes_drift','source SHA mismatch not blocked');
$result=NRY_Git_Publisher::execute($valid);
must(($result['status']??'')==='blocked_no_writes' && $writes===0
    && count($options)===0,'unexpected write or private backup with invalid raw source');
echo "ok: one immutable 59891 affiliate candidate, owner IDs, external allowlist, raw SHA gate, no writes\n";
